-- V42: eseguire dopo 01, 02, 03. Non apre gli ordini automaticamente.
begin;
alter table public.sr_products add column if not exists archived boolean not null default false;
alter table public.sr_orders add column if not exists tracking_token uuid not null default gen_random_uuid();
alter table public.sr_orders add column if not exists dispatch_date date;
alter table public.sr_orders add column if not exists tracking text not null default '';
alter table public.sr_orders add column if not exists internal_note text not null default '';
alter table public.sr_orders add column if not exists assignee text not null default '';
alter table public.sr_orders add column if not exists shipping_fee numeric(12,2) not null default 0;
alter table public.sr_orders add column if not exists final_total numeric(12,2);
alter table public.sr_orders add column if not exists customer_id uuid references auth.users(id) on delete set null;
alter table public.sr_orders add column if not exists source text not null default 'online';
alter table public.sr_orders add column if not exists consumed boolean not null default false;
create unique index if not exists sr_tracking_token_unique on public.sr_orders(tracking_token);
create table if not exists public.sr_mutations(id uuid primary key, actor uuid not null, created_at timestamptz not null default now());
alter table public.sr_mutations enable row level security;revoke all on public.sr_mutations from public,anon,authenticated;
create table if not exists public.sr_records(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('lotto','fornitore','promozione','notaCliente','task')),title text not null, detail text not null default '',date text not null default '',state text not null default '',created_at timestamptz not null default now());
alter table public.sr_records enable row level security;
revoke all on public.sr_records from public,anon,authenticated;
create or replace function public.sr_manager() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.sr_staff where user_id=auth.uid() and active and role in ('owner','manager'))$$;
revoke all on function public.sr_manager() from public,anon,authenticated;
create or replace function public.sr_owner() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.sr_staff where user_id=auth.uid() and active and role='owner')$$;
revoke all on function public.sr_owner() from public,anon,authenticated;
-- Coupons are discounts, not prepaid gift cards. Product prices are server-controlled.
alter table public.sr_orders add column if not exists coupon_code text not null default '';
alter table public.sr_orders add column if not exists discount numeric(12,2) not null default 0;
alter table public.sr_products add column if not exists promo_price numeric(12,2);
alter table public.sr_products add column if not exists promo_start timestamptz;
alter table public.sr_products add column if not exists promo_end timestamptz;
create table if not exists public.sr_coupons(code text primary key check(code~'^[A-Z0-9_-]{3,40}$'),kind text not null check(kind in ('percent','fixed')),value numeric(12,2) not null check(value>0),minimum numeric(12,2) not null default 0 check(minimum>=0),starts timestamptz,ends timestamptz,max_uses integer not null check(max_uses between 1 and 100000),active boolean not null default true,check(kind<>'percent' or value<=100),check(starts is null or ends is null or ends>starts));
alter table public.sr_coupons enable row level security;revoke all on public.sr_coupons from public,anon,authenticated;
create or replace function public.sr_effective_price(p public.sr_products) returns numeric language sql stable set search_path='' as $$select case when (p).promo_price is not null and (p).promo_price>0 and (p).promo_price<(p).price and ((p).promo_start is null or (p).promo_start<=now()) and ((p).promo_end is null or (p).promo_end>now()) then (p).promo_price else (p).price end$$;
revoke all on function public.sr_effective_price(public.sr_products) from public,anon,authenticated;
create or replace function public.sr_coupon_discount(c text,subtotal numeric) returns numeric language plpgsql stable security definer set search_path='' as $$declare cp public.sr_coupons%rowtype;begin if coalesce(c,'')='' then return 0;end if;select * into cp from public.sr_coupons where code=upper(btrim(c));if not found or not cp.active or (cp.starts is not null and cp.starts>now()) or (cp.ends is not null and cp.ends<=now()) or subtotal<cp.minimum or (select count(*) from public.sr_orders where coupon_code=cp.code and status<>'Annullata')>=cp.max_uses then raise exception 'Codice sconto non valido o non applicabile';end if;return least(subtotal,round(case when cp.kind='fixed' then cp.value else subtotal*cp.value/100 end,2));end $$;
revoke all on function public.sr_coupon_discount(text,numeric) from public,anon,authenticated;
create or replace function public.sr_quote(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare s jsonb;r record;pr public.sr_products%rowtype;sub numeric:=0;f numeric:=0;d numeric:=0;n numeric;begin
 select data into s from public.sr_settings where id=1;if not coalesce((s->>'open')::boolean,false) or coalesce((s->>'maintenance')::boolean,false) then raise exception 'Ordini online sospesi';end if;
 if jsonb_typeof(p->'items') is distinct from 'object' or p->'items'='{}'::jsonb or (select count(*) from jsonb_object_keys(p->'items'))>100 then raise exception 'Carrello non valido';end if;
 for r in select key,value from jsonb_each_text(p->'items') loop select * into pr from public.sr_products where id=r.key::integer;n:=r.value::numeric;if not found or not pr.active or pr.archived or n is null or n<=0 or n>1000 or (pr.unit='kg' and mod(n,.5)<>0) or (pr.unit='buc' and n<>trunc(n)) then raise exception 'Prodotto o quantità non valida';end if;sub:=sub+round(n*public.sr_effective_price(pr),2);end loop;
 if p->>'method'='scheduled' then if not (s->>'shipping')::boolean or sub<(s->>'min')::numeric then raise exception 'Spedizione non disponibile';end if;f:=case when sub>=(s->>'free')::numeric then 0 else (s->>'fee')::numeric end;elsif p->>'method' is distinct from 'pickup' then raise exception 'Modalità non valida';end if;d:=public.sr_coupon_discount(p->>'couponCode',sub);return jsonb_build_object('subtotal',sub,'fee',f,'discount',d,'total',sub+f-d);end $$;
create or replace function public.sr_coupons_staff() returns jsonb language plpgsql security definer set search_path='' as $$begin if not public.sr_manager() then raise exception 'Accesso negato';end if;return (select coalesce(jsonb_agg(to_jsonb(c) || jsonb_build_object('used',(select count(*) from public.sr_orders o where o.coupon_code=c.code and status<>'Annullata')) order by code),'[]') from public.sr_coupons c);end $$;
create or replace function public.sr_save_coupon(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare s jsonb;c text;begin if not public.sr_manager() then raise exception 'Accesso negato';end if;select data into s from public.sr_settings where id=1 for update;c:=upper(btrim(p->>'code'));if c is null or c !~ '^[A-Z0-9_-]{3,40}$' or coalesce((p->>'value')::numeric,0) not between .01 and 100000 or coalesce((p->>'minimum')::numeric,-1) not between 0 and 1000000 then raise exception 'Codice o valore non valido';end if;insert into public.sr_coupons(code,kind,value,minimum,starts,ends,max_uses,active) values(c,p->>'kind',(p->>'value')::numeric,(p->>'minimum')::numeric,nullif(p->>'starts','')::timestamptz,nullif(p->>'ends','')::timestamptz,(p->>'max_uses')::int,(p->>'active')::boolean) on conflict(code) do update set kind=excluded.kind,value=excluded.value,minimum=excluded.minimum,starts=excluded.starts,ends=excluded.ends,max_uses=excluded.max_uses,active=excluded.active;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'coupon_saved',jsonb_build_object('code',c));end $$;
revoke all on function public.sr_quote(jsonb),public.sr_coupons_staff(),public.sr_save_coupon(jsonb) from public,anon,authenticated;
grant execute on function public.sr_quote(jsonb) to anon,authenticated;
grant execute on function public.sr_coupons_staff(),public.sr_save_coupon(jsonb) to authenticated;

create or replace function public.sr_public_config() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('open',coalesce((data->>'open')::boolean,false) and not coalesce((data->>'maintenance')::boolean,false),'maintenance',coalesce((data->>'maintenance')::boolean,false),'shipping',coalesce((data->>'shipping')::boolean,false),'lead',greatest(24,coalesce((data->>'lead')::integer,24)),'capacity',data->'capacity','times',data->'times','closedDays',data->'closedDays','closedDates',data->'closedDates','min',data->'min','fee',data->'fee','free',data->'free','pickupAddress',data->'pickupAddress','bannerIt',data->'bannerIt','bannerRo',data->'bannerRo','dispatchDays',data->'dispatchDays','paymentMethods',coalesce(data->'paymentMethods','["store"]'::jsonb),'featured',data->'featured','heroIt',data->'heroIt','heroRo',data->'heroRo','heroPhoto',data->'heroPhoto','heroDescIt',data->'heroDescIt','heroDescRo',data->'heroDescRo','social',jsonb_build_object('video',data->'video','video2',data->'video2','video3',data->'video3','tiktok',data->'tiktok','instagram',data->'instagram','facebook',data->'facebook','email',data->'publicEmail'),'hoursIt',data->'hoursIt','hoursRo',data->'hoursRo','phone',data->'phone') from public.sr_settings where id=1$$;
-- Quantità vendibile: il prezzo e le scorte sono calcolati sul database.
create or replace function public.sr_catalog_v42() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'ro',p.ro,'it',p.it,'price',public.sr_effective_price(p),'basePrice',p.price,'cat',p.cat,'unit',p.unit,'image',p.image,'desc_it',p.desc_it,'desc_ro',p.desc_ro,'allergens',p.allergens,'sellable',greatest(0,p.stock-coalesce(r.qty,0)),'availability',case when p.stock-coalesce(r.qty,0)<=0 then 'unavailable' when p.stock-coalesce(r.qty,0)<=p.low then 'low' else 'available' end) order by p.id),'[]'::jsonb) from public.sr_products p left join lateral (select sum(l.qty) qty from public.sr_order_lines l join public.sr_orders o on o.id=l.order_id where l.product_id=p.id and not o.consumed and o.status in ('Da confermare','Confermata','In preparazione','Pronta')) r on true where p.active$$;
create or replace function public.sr_slot_ok(s jsonb,d date,t text,exclude_id uuid default null) returns boolean language plpgsql stable security definer set search_path='' as $$
declare stamp timestamptz; begin
 if d is null or t is null or t !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or not coalesce((s->'times') ? t,false) then return false; end if;
 stamp:=(d+t::time) at time zone 'Europe/Rome';
 return stamp>=now()+make_interval(hours=>greatest(24,coalesce((s->>'lead')::integer,24))) and d<=((now() at time zone 'Europe/Rome')::date+30) and not coalesce((s->'closedDays') @> jsonb_build_array(extract(dow from d)::int),false) and not coalesce((s->'closedDates') ? d::text,false) and (select count(*) from public.sr_orders where method='pickup' and pickup_at=stamp and status<>'Annullata' and (exclude_id is null or id<>exclude_id))<coalesce((s->>'capacity')::integer,5);
end $$;
revoke all on function public.sr_slot_ok(jsonb,date,text,uuid) from public,anon,authenticated;
create or replace function public.sr_slots(d date) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('times',coalesce(jsonb_agg(distinct t order by t) filter(where public.sr_slot_ok(s.data,d,t)),'[]'::jsonb)) from public.sr_settings s cross join lateral jsonb_array_elements_text(s.data->'times') t where s.id=1 and (s.data->>'open')::boolean$$;
-- Outbox: gli eventi sono persistiti, non dichiarati inviati.
create or replace function public.sr_queue(o public.sr_orders,ev text,s jsonb) returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.sr_notifications(order_id,channel,recipient,payload) values(o.id,'in_app','staff',jsonb_build_object('event',ev));
 if length(coalesce(s->>'shopEmail',''))>0 then insert into public.sr_notifications(order_id,channel,recipient,payload) values(o.id,'email',s->>'shopEmail',jsonb_build_object('event',ev,'audience','staff'));end if;
 if ev in ('new_order','Confermata','Pronta','Spedita','Annullata') then insert into public.sr_notifications(order_id,channel,recipient,payload) values(o.id,'email',o.customer->>'email',jsonb_build_object('event',ev,'audience','customer'));end if;
end $$;
revoke all on function public.sr_queue(public.sr_orders,text,jsonb) from public,anon,authenticated;
create or replace function public.sr_create_order(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb; req uuid; o public.sr_orders%rowtype; r record; pr public.sr_products%rowtype; amount numeric; reserved numeric; subtotal numeric:=0; fee numeric:=0; stamp timestamptz; m text; pm text; customer jsonb; manual boolean:=false; disc numeric:=0; coupon text; dispatch date; begin
 if jsonb_typeof(p) is distinct from 'object' or length(p::text)>24000 then raise exception 'Richiesta non valida';end if;
 req:=(p->>'requestId')::uuid; if req is null then raise exception 'Codice richiesta obbligatorio';end if;
 -- Serializza ordini, variazioni e capacità. I prodotti sono bloccati prima del controllo scorte.
 select data into s from public.sr_settings where id=1 for update;
 select * into o from public.sr_orders where request_id=req;
 if found then if lower(o.customer->>'email') is distinct from lower(btrim(p->>'email')) then raise exception 'Richiesta non valida';end if;return jsonb_build_object('id',o.id,'trackingToken',o.tracking_token,'total',o.total);end if;
 manual:=coalesce((p->>'manual')::boolean,false);if manual and not public.sr_manager() then raise exception 'Accesso negato';end if;
 if not manual and (not coalesce((s->>'open')::boolean,false) or coalesce((s->>'maintenance')::boolean,false)) then raise exception 'Ordini online sospesi';end if;
 if p->'consent' is distinct from 'true'::jsonb or length(btrim(coalesce(p->>'name',''))) not between 2 and 70 or length(coalesce(p->>'email',''))>120 or coalesce(p->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(regexp_replace(coalesce(p->>'phone',''),'[^0-9]','','g')) not between 6 and 20 or length(coalesce(p->>'phone',''))>30 or length(coalesce(p->>'notes',''))>200 or coalesce(p->>'lang','') not in ('it','ro') then raise exception 'Contatti o consenso non validi';end if;
 m:=p->>'method';pm:=p->>'payment';if m is null or m not in ('pickup','scheduled') or pm is null or pm not in ('store','bank','card','paypal') or not coalesce(coalesce(s->'paymentMethods','["store"]'::jsonb) ? pm,false) or (m<>'pickup' and pm='store') then raise exception 'Modalità o pagamento non disponibile';end if;
 if not manual and (select count(*) from public.sr_orders ox where lower(ox.customer->>'email')=lower(btrim(p->>'email')) and ox.status in ('Da confermare','Confermata','In preparazione','Pronta'))>=5 then raise exception 'Troppi ordini aperti per questo contatto';end if;
 if m='pickup' then if not public.sr_slot_ok(s,(p->>'pickupDate')::date,p->>'pickupTime') then raise exception 'Orario non disponibile: preavviso minimo 24 ore';end if;stamp:=((p->>'pickupDate')::date+(p->>'pickupTime')::time) at time zone 'Europe/Rome';else
 if not coalesce((s->>'shipping')::boolean,false) or coalesce(p->>'cap','') !~ '^[0-9]{5}$' or not coalesce((s->'allowedCaps') ? (p->>'cap'),false) or coalesce(p->>'province','') !~ '^[A-Z]{2}$' or length(btrim(coalesce(p->>'address',''))) not between 3 and 160 or length(btrim(coalesce(p->>'city',''))) not between 2 and 80 then raise exception 'Spedizione o indirizzo non disponibile';end if;end if;
 if jsonb_typeof(p->'items') is distinct from 'object' or p->'items'='{}'::jsonb or (select count(*) from jsonb_object_keys(p->'items'))>100 then raise exception 'Carrello non valido';end if;
 for r in select key,value from jsonb_each_text(p->'items') order by key::integer loop
 amount:=r.value::numeric; if amount is null or amount<=0 or amount>1000 or amount<>round(amount,3) then raise exception 'Quantità non valida';end if;
 select * into pr from public.sr_products where id=r.key::integer for update;
 if not found or not pr.active or pr.archived or pr.price<=0 or (pr.unit='buc' and amount<>trunc(amount)) or (pr.unit='kg' and mod(amount,.5)<>0) then raise exception 'Prodotto o quantità non valida';end if;
 select coalesce(sum(l.qty),0) into reserved from public.sr_order_lines l join public.sr_orders a on a.id=l.order_id where l.product_id=pr.id and not a.consumed and a.status in ('Da confermare','Confermata','In preparazione','Pronta');
 if amount>pr.stock-reserved then raise exception 'Scorta insufficiente: %',pr.it;end if;subtotal:=subtotal+round(amount*public.sr_effective_price(pr),2);
 end loop;
 if m='scheduled' then select min(x::date) into dispatch from generate_series(((now()+interval '24 hours') at time zone 'Europe/Rome')::date+1,((now() at time zone 'Europe/Rome')::date+30),interval '1 day') x where coalesce((s->'dispatchDays') @> jsonb_build_array(extract(dow from x)::int),false) and not coalesce((s->'closedDates') ? x::date::text,false);if dispatch is null then raise exception 'Nessuna giornata di spedizione disponibile';end if;if subtotal<(s->>'min')::numeric then raise exception 'Minimo spedizione non raggiunto';end if;fee:=case when subtotal>=(s->>'free')::numeric then 0 else (s->>'fee')::numeric end;end if;
 coupon:=upper(btrim(coalesce(p->>'couponCode','')));disc:=public.sr_coupon_discount(coupon,subtotal);if not manual and (p ? 'expectedTotal') and (p->>'expectedTotal')::numeric is distinct from subtotal+fee-disc then raise exception 'Totale cambiato: ricontrolla il carrello';end if;
 customer:=jsonb_build_object('name',btrim(p->>'name'),'email',lower(btrim(p->>'email')),'phone',p->>'phone','lang',p->>'lang','notes',coalesce(p->>'notes',''),'address',case when m='scheduled' then p->>'address' else '' end,'city',case when m='scheduled' then p->>'city' else '' end,'cap',case when m='scheduled' then p->>'cap' else '' end,'province',case when m='scheduled' then p->>'province' else '' end);
 insert into public.sr_orders(request_id,method,pickup_at,customer,total,payment_method,shipping_fee,customer_id,source,coupon_code,discount,dispatch_date) values(req,m,stamp,customer,subtotal+fee-disc,pm,fee,case when manual then null else auth.uid() end,case when manual then 'manual' else 'online' end,coupon,disc,dispatch) returning * into o;
 insert into public.sr_order_lines(order_id,product_id,qty,unit_price,name_it,name_ro) select o.id,pp.id,x.value::numeric,public.sr_effective_price(pp),pp.it,pp.ro from jsonb_each_text(p->'items') x join public.sr_products pp on pp.id=x.key::integer;
 perform public.sr_queue(o,'new_order',s);insert into public.sr_audit(actor,action,detail) values(auth.uid(),'order_created',jsonb_build_object('id',o.id,'source',o.source));
 return jsonb_build_object('id',o.id,'trackingToken',o.tracking_token,'total',o.total);
end $$;
create or replace function public.sr_track(k uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'status',status,'method',method,'pickup_at',pickup_at,'total',coalesce(final_total,total),'payment_status',payment_status,'tracking',tracking,'dispatch_date',dispatch_date,'created_at',created_at,'bankInstructions',case when payment_method='bank' and status in ('Confermata','In preparazione','Pronta') then (select data->>'bankInstructions' from public.sr_settings where id=1) else null end) from public.sr_orders where tracking_token=k$$;
create or replace function public.sr_update_order(p jsonb) returns void language plpgsql security definer set search_path='' as $$
declare s jsonb;o public.sr_orders%rowtype;target text; r record; pr public.sr_products%rowtype;reserved numeric; newslot timestamptz; paid numeric; refund numeric; a numeric; subtotal numeric;fee numeric; begin
 if not public.sr_manager() then raise exception 'Accesso negato';end if;
 select data into s from public.sr_settings where id=1 for update;if p ? 'operationId' then if exists(select 1 from public.sr_mutations where id=(p->>'operationId')::uuid and actor=auth.uid()) then return;end if;insert into public.sr_mutations(id,actor) values((p->>'operationId')::uuid,auth.uid());else raise exception 'Codice operazione obbligatorio';end if;select * into o from public.sr_orders where id=(p->>'id')::uuid for update;if not found then raise exception 'Ordine non trovato';end if;
 target:=coalesce(p->>'status',o.status);
 if target<>o.status and not ((o.status='Da confermare' and target in ('Confermata','Annullata')) or (o.status='Confermata' and target in ('In preparazione','Annullata')) or (o.status='In preparazione' and target in ('Pronta','Spedita','Annullata')) or (o.status='Pronta' and target in ('Ritirata','Annullata')) or (o.status='Spedita' and target='Consegnata')) then raise exception 'Transizione non consentita';end if;
 if (target='Spedita' and o.method='pickup') or (target in ('Pronta','Ritirata') and o.method<>'pickup') then raise exception 'Stato non compatibile';end if;
 select coalesce(sum(amount) filter(where kind='payment'),0),coalesce(sum(amount) filter(where kind='refund'),0) into paid,refund from public.sr_payments where order_id=o.id;
 if p ? 'lines' then
 if o.consumed or o.status='Annullata' or paid>0 or o.coupon_code<>'' or jsonb_typeof(p->'lines')<>'array' or jsonb_array_length(p->'lines') not between 1 and 100 or (select count(distinct (x->>'id')::int) from jsonb_array_elements(p->'lines') x)<>jsonb_array_length(p->'lines') then raise exception 'Righe non modificabili';end if;
 perform 1 from public.sr_products where id in(select product_id from public.sr_order_lines where order_id=o.id union select (x->>'id')::integer from jsonb_array_elements(p->'lines') x) order by id for update;
 delete from public.sr_order_lines where order_id=o.id;
 for r in select (x->>'id')::int id,(x->>'qty')::numeric q,(x->>'price')::numeric v from jsonb_array_elements(p->'lines') x loop
 select * into pr from public.sr_products where id=r.id;if not found or not pr.active or pr.archived or r.q is null or r.q<=0 or r.q>1000 or r.q<>round(r.q,3) or (pr.unit='buc' and r.q<>trunc(r.q)) or r.v is null or r.v<0 or r.v>1000000 or r.v<>round(r.v,2) then raise exception 'Riga non valida';end if;
 select coalesce(sum(l.qty),0) into reserved from public.sr_order_lines l join public.sr_orders z on z.id=l.order_id where l.product_id=pr.id and not z.consumed and z.status in ('Da confermare','Confermata','In preparazione','Pronta');if r.q>pr.stock-reserved then raise exception 'Scorte insufficienti';end if;
 insert into public.sr_order_lines values(o.id,pr.id,r.q,r.v,pr.it,pr.ro);end loop;end if;
 if p ? 'day' and o.method='pickup' then newslot:=((p->>'day')::date+(p->>'time')::time) at time zone 'Europe/Rome';if newslot is distinct from o.pickup_at then if o.consumed or o.status='Annullata' or not public.sr_slot_ok(s,(p->>'day')::date,p->>'time',o.id) then raise exception 'Orario non disponibile';end if;o.pickup_at:=newslot;end if;end if;
 fee:=coalesce((p->>'fee')::numeric,o.shipping_fee);if fee<0 or fee>100000 or (o.method='pickup' and fee<>0) then raise exception 'Spedizione non valida';end if;
 select greatest(0,coalesce(sum(round(qty*unit_price,2)),0)-o.discount) into subtotal from public.sr_order_lines where order_id=o.id;
 if (p ? 'lines' or p ? 'fee' or p ? 'final') and (o.consumed or o.status='Annullata' or paid>0) then raise exception 'Importo non modificabile';end if;
 o.final_total:=coalesce((p->>'final')::numeric,o.final_total);if o.final_total<0 or o.final_total>10000000 then raise exception 'Totale non valido';end if;
 if p ? 'paymentAmount' then a:=(p->>'paymentAmount')::numeric;if a is null or a<=0 or a<>round(a,2) or paid-refund+a>coalesce(o.final_total,subtotal+fee) or target='Annullata' then raise exception 'Incasso non valido';end if;insert into public.sr_payments(order_id,amount,kind) values(o.id,a,'payment');paid:=paid+a;end if;
 if p ? 'refundAmount' then if not public.sr_owner() then raise exception 'Solo il titolare può registrare rimborsi';end if;a:=(p->>'refundAmount')::numeric;if a is null or a<=0 or a<>round(a,2) or a>paid-refund then raise exception 'Rimborso non valido';end if;insert into public.sr_payments(order_id,amount,kind) values(o.id,a,'refund');refund:=refund+a;end if;
 if target='Annullata' and paid>refund then raise exception 'Registra il rimborso verificato prima di annullare';end if;
 if target in ('Ritirata','Spedita') and not o.consumed then if paid-refund<coalesce(o.final_total,subtotal+fee) then raise exception 'Registra il pagamento prima della consegna';end if;for r in select product_id,qty from public.sr_order_lines where order_id=o.id order by product_id loop update public.sr_products set stock=stock-r.qty,updated_at=now() where id=r.product_id and stock>=r.qty;if not found then raise exception 'Scorta insufficiente';end if;end loop;o.consumed:=true;end if;
 if coalesce((p->>'sendPayment')::boolean,false) then raise exception 'Invio link pagamento non configurato';end if;
 update public.sr_orders set status=target,pickup_at=o.pickup_at,shipping_fee=fee,total=subtotal+fee,final_total=o.final_total,consumed=o.consumed,internal_note=left(coalesce(p->>'internal',o.internal_note),4000),tracking=left(coalesce(p->>'tracking',o.tracking),200),assignee=left(coalesce(p->>'assignee',o.assignee),200),payment_status=case when paid>0 and refund=paid then 'refunded' when paid-refund>=coalesce(o.final_total,subtotal+fee) then 'paid' when paid-refund>0 then 'partial' else 'pending' end where id=o.id;
 if target<>o.status then perform public.sr_queue(o,target,s);end if;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'order_updated',jsonb_build_object('id',o.id,'status',target,'payment',paid,'refund',refund));
end $$;
create or replace function public.sr_save_settings(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare s jsonb;begin
 if not public.sr_owner() then raise exception 'Solo titolare';end if;
 if jsonb_typeof(p) is distinct from 'object' or length(p::text)>30000 or coalesce((p->>'lead')::int,0)<24 or coalesce((p->>'lead')::int,0)>720 or coalesce((p->>'capacity')::int,0) not between 1 and 100 or coalesce((p->>'min')::numeric,-1) not between 0 and 1000000 or coalesce((p->>'fee')::numeric,-1) not between 0 and 1000000 or coalesce((p->>'free')::numeric,-1) not between coalesce((p->>'min')::numeric,0) and 1000000 or jsonb_typeof(p->'times') is distinct from 'array' or jsonb_array_length(p->'times') not between 1 and 48 or exists(select 1 from jsonb_array_elements_text(p->'times') x where x !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') or jsonb_typeof(p->'closedDays') is distinct from 'array' or exists(select 1 from jsonb_array_elements_text(p->'closedDays') x where x !~ '^[0-6]$') or jsonb_typeof(p->'closedDates') is distinct from 'array' or exists(select 1 from jsonb_array_elements_text(p->'closedDates') x where x !~ '^\d{4}-\d{2}-\d{2}$') then raise exception 'Impostazioni non valide';end if;
 select data into s from public.sr_settings where id=1 for update;
 if coalesce(p->>'heroPhoto','')<>'' and p->>'heroPhoto' !~ '^assets/[a-zA-Z0-9_-]+\.(webp|png|jpg|jpeg)$' and p->>'heroPhoto' !~ '^https://[^[:space:]<>"'']+$' then raise exception 'Foto homepage non valida';end if;
 if (p->>'open')::boolean and not coalesce((p->>'catalogReviewed')::boolean,false) then raise exception 'Conferma di aver verificato catalogo, prezzi, allergeni e condizioni di vendita';end if;
 if (p->>'shipping')::boolean and (jsonb_typeof(p->'allowedCaps') is distinct from 'array' or jsonb_array_length(p->'allowedCaps')=0 or exists(select 1 from jsonb_array_elements_text(p->'allowedCaps') x where x !~ '^[0-9]{5}$') or jsonb_typeof(p->'dispatchDays') is distinct from 'array' or jsonb_array_length(p->'dispatchDays')=0 or exists(select 1 from jsonb_array_elements_text(p->'dispatchDays') x where x !~ '^[0-6]$') or not coalesce((p->>'shippingReviewed')::boolean,false) or not coalesce((p->>'bankEnabled')::boolean,false)) then raise exception 'Verifica trasportatore, CAP e bonifico prima di aprire le spedizioni';end if;
 if coalesce((p->>'bankEnabled')::boolean,false) and length(btrim(coalesce(p->>'bankInstructions','')))<10 then raise exception 'Inserisci istruzioni bonifico';end if;
 update public.sr_settings set data=s||p||jsonb_build_object('paymentMethods',case when coalesce((p->>'bankEnabled')::boolean,false) then '["store","bank"]'::jsonb else '["store"]'::jsonb end) where id=1;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'settings_saved',jsonb_build_object('open',p->'open','shipping',p->'shipping'));end $$;
create or replace function public.sr_record(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare rid uuid;begin if not public.sr_manager() then raise exception 'Accesso negato';end if;rid:=nullif(p->>'id','')::uuid;if coalesce((p->>'delete')::boolean,false) then delete from public.sr_records where id=rid;else if length(btrim(coalesce(p->>'title',''))) not between 1 and 250 or length(coalesce(p->>'detail',''))>5000 then raise exception 'Dati non validi';end if;insert into public.sr_records(id,kind,title,detail,date,state) values(coalesce(rid,gen_random_uuid()),p->>'kind',p->>'title',coalesce(p->>'detail',''),coalesce(p->>'date',''),coalesce(p->>'state','')) on conflict(id) do update set title=excluded.title,detail=excluded.detail,date=excluded.date,state=excluded.state;end if;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'record_changed',jsonb_build_object('kind',p->>'kind'));end $$;
create or replace function public.sr_staff_snapshot() returns jsonb language plpgsql security definer set search_path='' as $$begin if not public.sr_manager() then raise exception 'Accesso negato';end if;return jsonb_build_object('products',(select coalesce(jsonb_agg(to_jsonb(p) order by id),'[]') from public.sr_products p),'orders',(select coalesce(jsonb_agg(to_jsonb(o) order by created_at desc),'[]') from public.sr_orders o),'lines',(select coalesce(jsonb_agg(to_jsonb(l)),'[]') from public.sr_order_lines l),'payments',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.sr_payments p),'settings',(select data from public.sr_settings where id=1),'audit',(select coalesce(jsonb_agg(to_jsonb(a) order by created_at desc),'[]') from (select * from public.sr_audit order by id desc limit 200) a),'notifications',(select coalesce(jsonb_agg(to_jsonb(n) order by created_at desc),'[]') from (select * from public.sr_notifications order by created_at desc limit 200)n),'records',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from public.sr_records r));end $$;
-- Audit di movimenti fisici, inclusi aggiornamenti catalogo già esistenti.
create or replace function public.sr_stock_audit() returns trigger language plpgsql security definer set search_path='' as $$begin if old.stock is distinct from new.stock then insert into public.sr_audit(actor,action,detail) values(auth.uid(),'stock_movement',jsonb_build_object('id',new.id,'old',old.stock,'new',new.stock,'delta',new.stock-old.stock));end if;return new;end $$;
revoke all on function public.sr_stock_audit() from public,anon,authenticated;
drop trigger if exists sr_stock_audit on public.sr_products;create trigger sr_stock_audit after update of stock on public.sr_products for each row execute function public.sr_stock_audit();
