create or replace function public.sr_save_product_v42(p jsonb) returns integer language plpgsql security definer set search_path='' as $$declare pid int;begin
 if not public.sr_manager() then raise exception 'Accesso negato';end if;
 if exists(select 1 from public.sr_products where id=(p->>'id')::int and archived) then raise exception 'Ripristina prima il prodotto';end if;
 if exists(select 1 from jsonb_each_text(p) x where x.key in ('ingredients_it','ingredients_ro','allergens_ro','storage_it','storage_ro','nutrition','format_it','format_ro') and length(x.value)>5000) or length(coalesce(p->>'variant_group',''))>100 or length(coalesce(p->>'supplier',''))>200 or (coalesce(p->>'barcode','')<>'' and p->>'barcode' !~ '^[0-9]{8,14}$') then raise exception 'Dati prodotto non validi';end if;
 if p ? 'promo_price' and nullif(p->>'promo_price','') is not null and ((p->>'promo_price')::numeric<=0 or (p->>'promo_price')::numeric>=(p->>'price')::numeric or (nullif(p->>'promo_start','') is not null and nullif(p->>'promo_end','') is not null and (p->>'promo_start')::timestamptz>=(p->>'promo_end')::timestamptz)) then raise exception 'Prezzo o periodo promozionale non valido';end if;
 pid:=public.sr_save_product(p);
 update public.sr_products set ingredients_it=coalesce(p->>'ingredients_it',ingredients_it),ingredients_ro=coalesce(p->>'ingredients_ro',ingredients_ro),allergens_ro=coalesce(p->>'allergens_ro',allergens_ro),storage_it=coalesce(p->>'storage_it',storage_it),storage_ro=coalesce(p->>'storage_ro',storage_ro),nutrition=coalesce(p->>'nutrition',nutrition),format_it=coalesce(p->>'format_it',format_it),format_ro=coalesce(p->>'format_ro',format_ro),variant_group=coalesce(p->>'variant_group',variant_group),barcode=coalesce(p->>'barcode',barcode),supplier=coalesce(p->>'supplier',supplier),promo_price=case when p ? 'promo_price' then nullif(p->>'promo_price','')::numeric else promo_price end,promo_start=case when p ? 'promo_start' then nullif(p->>'promo_start','')::timestamptz else promo_start end,promo_end=case when p ? 'promo_end' then nullif(p->>'promo_end','')::timestamptz else promo_end end where id=pid;
 return pid;end $$;
create or replace function public.sr_bulk_products(p jsonb) returns integer language plpgsql security definer set search_path='' as $$declare r record;v public.sr_products%rowtype;n int:=0;begin
 if not public.sr_manager() then raise exception 'Accesso negato';end if;if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) not between 1 and 200 or (select count(distinct x->>'id') from jsonb_array_elements(p)x)<>jsonb_array_length(p) then raise exception 'Selezione non valida';end if;
 for r in select x from jsonb_array_elements(p)x order by (x->>'id')::int loop select * into v from public.sr_products where id=(r.x->>'id')::int for update;if not found then raise exception 'Prodotto non trovato';end if;
 if v.updated_at is distinct from (r.x->>'updated_at')::timestamptz then raise exception 'Dati modificati da un altro operatore';end if;
 perform public.sr_save_product(to_jsonb(v)||jsonb_build_object('descIt',v.desc_it,'descRo',v.desc_ro,'price',coalesce(r.x->'price',to_jsonb(v.price)),'stock',coalesce(r.x->'stock',to_jsonb(v.stock))));n:=n+1;end loop;return n;end $$;
create or replace function public.sr_archive_product(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare v public.sr_products%rowtype; a boolean;begin if not public.sr_manager() then raise exception 'Accesso negato';end if;
 select * into v from public.sr_products where id=(p->>'id')::int for update;if not found then raise exception 'Prodotto non trovato';end if;a:=coalesce((p->>'archive')::boolean,true);if a then perform public.sr_save_product(to_jsonb(v)||jsonb_build_object('active',false,'descIt',v.desc_it,'descRo',v.desc_ro));end if;update public.sr_products set archived=a,updated_at=now() where id=v.id;insert into public.sr_audit(actor,action,detail) values(auth.uid(),case when a then 'product_archived' else 'product_restored' end,jsonb_build_object('id',v.id));end $$;
create or replace function public.sr_catalog_v42() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'ro',p.ro,'it',p.it,'price',public.sr_effective_price(p),'basePrice',p.price,'cat',p.cat,'unit',p.unit,'image',p.image,'desc_it',p.desc_it,'desc_ro',p.desc_ro,'allergens',p.allergens,'allergens_ro',p.allergens_ro,'ingredients_it',p.ingredients_it,'ingredients_ro',p.ingredients_ro,'storage_it',p.storage_it,'storage_ro',p.storage_ro,'format_it',p.format_it,'format_ro',p.format_ro,'nutrition',p.nutrition,'variant_group',p.variant_group,'sellable',greatest(0,p.stock-coalesce(r.qty,0)),'availability',case when p.stock-coalesce(r.qty,0)<=0 then 'unavailable' when p.stock-coalesce(r.qty,0)<=p.low then 'low' else 'available' end) order by p.id),'[]'::jsonb) from public.sr_products p left join lateral (select sum(l.qty) qty from public.sr_order_lines l join public.sr_orders o on o.id=l.order_id where l.product_id=p.id and not o.consumed and o.status in ('Da confermare','Confermata','In preparazione','Pronta')) r on true where p.active and not p.archived$$;
-- Customer account and purchase-verified reviews. Reviews are moderated before publishing.
create table if not exists public.sr_reviews(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, product_id int not null references public.sr_products(id), stars int not null check(stars between 1 and 5), body text not null check(length(body) between 1 and 1500), approved boolean not null default false, created_at timestamptz not null default now(),unique(user_id,product_id));
alter table public.sr_reviews enable row level security;revoke all on public.sr_reviews from public,anon,authenticated;
create or replace function public.sr_my_orders() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'created_at',o.created_at,'status',o.status,'total',coalesce(o.final_total,o.total),'trackingToken',o.tracking_token,'products',(select coalesce(jsonb_agg(jsonb_build_object('id',l.product_id,'it',l.name_it,'ro',l.name_ro,'qty',l.qty)),'[]') from public.sr_order_lines l where l.order_id=o.id)) order by o.created_at desc),'[]') from public.sr_orders o where auth.uid() is not null and o.customer_id=auth.uid()$$;
create or replace function public.sr_submit_review(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare pid int;begin if auth.uid() is null then raise exception 'Accedi';end if;pid:=(p->>'product_id')::int;if not exists(select 1 from public.sr_order_lines l join public.sr_orders o on o.id=l.order_id where o.customer_id=auth.uid() and o.status in ('Ritirata','Consegnata') and l.product_id=pid) then raise exception 'Recensione riservata a un acquisto completato';end if;insert into public.sr_reviews(user_id,product_id,stars,body) values(auth.uid(),pid,(p->>'stars')::int,btrim(p->>'body')) on conflict(user_id,product_id) do update set stars=excluded.stars,body=excluded.body,approved=false,created_at=now();end $$;
create or replace function public.sr_product_reviews(pid int) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('stars',r.stars,'body',r.body,'created_at',r.created_at) order by r.created_at desc),'[]') from (select * from public.sr_reviews where product_id=pid and approved order by created_at desc limit 50) r$$;
create or replace function public.sr_review_queue() returns jsonb language plpgsql security definer set search_path='' as $$begin if not public.sr_manager() then raise exception 'Accesso negato';end if;return (select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'product',p.it,'stars',r.stars,'body',r.body,'approved',r.approved,'created_at',r.created_at) order by r.created_at desc),'[]') from public.sr_reviews r join public.sr_products p on p.id=r.product_id);end $$;
create or replace function public.sr_moderate_review(p jsonb) returns void language plpgsql security definer set search_path='' as $$begin if not public.sr_manager() then raise exception 'Accesso negato';end if;update public.sr_reviews set approved=(p->>'approved')::boolean where id=(p->>'id')::uuid;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'review_moderated',jsonb_build_object('id',p->>'id','approved',p->'approved'));end $$;
-- Owner manages only existing Auth accounts. No secret key or privileged Auth API in the browser.
create or replace function public.sr_team() returns jsonb language plpgsql security definer set search_path='' as $$begin if not public.sr_owner() then raise exception 'Accesso negato';end if;return (select coalesce(jsonb_agg(jsonb_build_object('id',s.user_id,'name',u.email,'role',s.role,'active',s.active)),'[]') from public.sr_staff s join auth.users u on u.id=s.user_id);end $$;
create or replace function public.sr_set_staff(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare uid uuid;ro text;begin if not public.sr_owner() then raise exception 'Accesso negato';end if;select id into uid from auth.users where lower(email)=lower(btrim(p->>'name'));if uid is null then raise exception 'Crea prima l’account in Authentication > Users';end if;if uid=auth.uid() or exists(select 1 from public.sr_staff where user_id=uid and role='owner') then raise exception 'Account titolare protetto';end if;ro:=coalesce(p->>'role',(select role from public.sr_staff where user_id=uid));if ro is null or ro<>'manager' then raise exception 'In questa versione è disponibile il ruolo Manager; ruoli limitati da completare';end if;insert into public.sr_staff(user_id,role,active) values(uid,ro,coalesce((p->>'active')::boolean,true)) on conflict(user_id) do update set role=excluded.role,active=excluded.active;insert into public.sr_audit(actor,action,detail) values(auth.uid(),'staff_access_changed',jsonb_build_object('id',uid,'role',ro,'active',p->'active'));end $$;
